// Wake head: single MultiProto head, sigmoid over cosine logits.
static inline float kws_postprocess_wake(const int8_t *out_i8, float out_scale,
                                         int out_zero) {
    float feat[KWS_HEAD_D]; float norm = 0.0f;
    for (int i = 0; i < KWS_HEAD_D; i++) {
        feat[i] = ((float)out_i8[i] - (float)out_zero) * out_scale;
        norm += feat[i] * feat[i];
    }
    norm = sqrtf(norm) + 1e-12f;
    for (int i = 0; i < KWS_HEAD_D; i++) feat[i] /= norm;
    float logit = KWS_WAKE_FC_B;
    for (int k = 0; k < KWS_WAKE_K; k++) {
        float cos = 0.0f;
        for (int i = 0; i < KWS_HEAD_D; i++) cos += feat[i] * KWS_WAKE_PROTO_NORM[k][i];
        logit += KWS_WAKE_FC_W[k] * (cos / KWS_WAKE_ABS_TEMP);
    }
    return 1.0f / (1.0f + expf(-logit));
}

// Multi-keyword head: dequant int8[256] -> N sigmoid probs (word order above).
static inline int kws_postprocess_cmd(const int8_t *out_i8, float out_scale,
                                        int out_zero, float *probs) {
    float feat[KWS_HEAD_D]; float norm = 0.0f;
    for (int i = 0; i < KWS_HEAD_D; i++) {
        feat[i] = ((float)out_i8[i] - (float)out_zero) * out_scale;
        norm += feat[i] * feat[i];
    }
    norm = sqrtf(norm) + 1e-12f;
    for (int i = 0; i < KWS_HEAD_D; i++) feat[i] /= norm;
    for (int w = 0; w < KWS_CMD_N; w++) {
        float logit = KWS_CMD_FC_B[w];
        for (int k = 0; k < KWS_CMD_K; k++) {
            float cos = 0.0f;
            for (int i = 0; i < KWS_HEAD_D; i++) cos += feat[i] * KWS_CMD_PROTO_NORM[w][k][i];
            logit += KWS_CMD_FC_W[w][k] * (cos / KWS_CMD_ABS_TEMP[w]);
        }
        probs[w] = 1.0f / (1.0f + expf(-logit));
    }
    return KWS_CMD_N;
}

static inline void kws_quantize_mel(const float *mel, int8_t *out, int n, float in_scale, int in_zero) {
    for (int i = 0; i < n; i++) {
        int q = (int)lrintf(mel[i] / in_scale) + in_zero;
        out[i] = (int8_t)(q < -128 ? -128 : (q > 127 ? 127 : q));
    }
}
